import{_ as o}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{c as e,o as n,af as r}from"./chunks/mermaid.YsAH9es0.js";import"./chunks/cytoscape.C2CwDKBM.js";import"./chunks/dayjs.C32PoDnw.js";const k=JSON.parse('{"title":"从编码提效到端到端交付：人机协作流水线实践卡","description":"阿里云《AI Agent Handbook》第 25 章实践卡：需求门控 R≤L、契约链九工序与两条硬约束、四视角交叉质检、数字分身权限模型、三层审计归因 Loop 与端到端成本底线；每张卡附前置条件、失败模式、可验证指标与一人公司降级做法。","frontmatter":{"title":"从编码提效到端到端交付：人机协作流水线实践卡","description":"阿里云《AI Agent Handbook》第 25 章实践卡：需求门控 R≤L、契约链九工序与两条硬约束、四视角交叉质检、数字分身权限模型、三层审计归因 Loop 与端到端成本底线；每张卡附前置条件、失败模式、可验证指标与一人公司降级做法。","domain":"practice","tags":["agent","efficiency","team"]},"headers":[],"relativePath":"zh/practice/agent-handbook/case-human-ai-pipeline.md","filePath":"zh/practice/agent-handbook/case-human-ai-pipeline.md","lastUpdated":1793275122000}'),u={name:"zh/practice/agent-handbook/case-human-ai-pipeline.md"};function a(i,t,s,l,q,p){return n(),e("div",null,[...t[0]||(t[0]=[r(`<h1 id="从编码提效到端到端交付-人机协作流水线实践卡" tabindex="-1">从编码提效到端到端交付：人机协作流水线实践卡 <a class="header-anchor" href="#从编码提效到端到端交付-人机协作流水线实践卡" aria-label="Permalink to &quot;从编码提效到端到端交付：人机协作流水线实践卡&quot;">​</a></h1><blockquote><p>来源：<a href="https://github.com/aliyun/ai-agent-handbook/blob/HEAD/06-case-study/%E7%AC%AC25%E7%AB%A0%20%E7%A0%94%E5%8F%91%E6%95%88%E8%83%BD/%E4%BB%8E%E7%BC%96%E7%A0%81%E6%8F%90%E6%95%88%E5%88%B0%E7%AB%AF%E5%88%B0%E7%AB%AF%E4%BA%A4%E4%BB%98%EF%BC%8C%E4%BA%91%E9%80%9A%E4%BF%A1%E7%9A%84%E4%BA%BA%E6%9C%BA%E5%8D%8F%E4%BD%9C%E5%AE%9E%E8%B7%B5.md" target="_blank" rel="noreferrer">阿里云《AI Agent Handbook》第 25 章《从编码提效到端到端交付，云通信的人机协作实践》</a></p><p>读法：六张卡呈递进关系——先门控（卡 1）定接单边界，再契约（卡 2）固化协作，再质检（卡 3）保证质量；权限模型（卡 4）与审计归因（卡 5）贯穿始终；成本治理（卡 6）决定这套体系能跑多大。每张卡的「证据分级」字段单独标注阿里云团队主张 / 内部数据 vs 可独立复现的做法。所有引文均为原文逐字片段。</p></blockquote><h2 id="导读-编码提效-交付提效" tabindex="-1">导读：编码提效 ≠ 交付提效 <a class="header-anchor" href="#导读-编码提效-交付提效" aria-label="Permalink to &quot;导读：编码提效 ≠ 交付提效&quot;">​</a></h2><p>云通信研发团队把 AI 落地切成三段走：2024 年把代码补全、对话式编程、生成式 IDE 铺到日常开发；2025 年把规范与领域知识沉淀为宪法、Skill 等物料，让 AI 干活有章可循；2026 年全面走向 Agent 化作业模式，正朝端到端交付迈进。三段走完，出现一个反直觉结果：</p><blockquote><p>&quot;AI生成的代码量翻了N倍，但端到端交付的效率却没有同步跃升。&quot;</p></blockquote><p>复盘后定位到三个&quot;人衔接节点&quot;——需求澄清对齐消耗人力、代码评审跟不上产出、测试排期成为瓶颈。原文给出的总结是：</p><blockquote><p>&quot;只要交付链路里存在由人衔接的节点，该节点就决定了吞吐上限。&quot;</p></blockquote><p>围绕这个判断，全章提出三组对应关系：协作问题 → 标准化作业流水线；边界问题 → 数字分身；落地问题 → 稳定优先、渐进放开。本页六张卡就是把这三组对应关系拆成可照做的步骤。</p><h2 id="证据分级-团队主张-vs-可独立复现的做法" tabindex="-1">证据分级：团队主张 vs 可独立复现的做法 <a class="header-anchor" href="#证据分级-团队主张-vs-可独立复现的做法" aria-label="Permalink to &quot;证据分级：团队主张 vs 可独立复现的做法&quot;">​</a></h2><p>阅读本章请先分清两类信息，后文每张卡的&quot;证据分级&quot;字段再逐条标注：</p><table tabindex="0"><thead><tr><th>类型</th><th>内容</th><th>怎么用</th></tr></thead><tbody><tr><td>阿里云团队主张 / 内部数据</td><td>三段演进时间线；前置条件齐备情况下&quot;单人2-3天完成整个系统的初始化&quot;；&quot;AI生成的代码量翻了N倍&quot;；&quot;待补齐该规则模板后，同类需求的返工显著减少&quot;；&quot;越用越强&quot;等效果描述；第五节的成本底线与人机混编展望（原文列在&quot;未来规划&quot;段落）</td><td>当作参照系与动机看，不要当基准值。自己的数必须自己测</td></tr><tr><td>可独立复现的做法</td><td>R≤L 需求门控与升降级；契约链九工序与两条硬约束；四视角交叉质检与负责人收口；三层正交审计与归因路由；模型分档/上下文管理/错峰的成本治理思路；数字分身复用组织既有权限与责任绑定</td><td>机制照搬，参数（R 的维度、L 的评分、检查点清单、归因路由分类）按自己业务重定</td></tr></tbody></table><h2 id="实践卡-1-需求门控——用风险等级-r-对照能力等级-l-再决定谁接单" tabindex="-1">实践卡 1：需求门控——用风险等级 R 对照能力等级 L，再决定谁接单 <a class="header-anchor" href="#实践卡-1-需求门控——用风险等级-r-对照能力等级-l-再决定谁接单" aria-label="Permalink to &quot;实践卡 1：需求门控——用风险等级 R 对照能力等级 L，再决定谁接单&quot;">​</a></h2><p><strong>要解决的问题</strong>：Agent 能力边界是动态的，需求风险是分级的。没有门禁，团队要么因噎废食（迟迟不引入 AI），要么急于求成（把质量完全押给模型）；有了门禁，才能&quot;从简单需求起步、边界一步步外扩&quot;。</p><p><strong>具体做法（步骤 / 机制 / 指标）</strong>：</p><ol><li><p>每个需求进入时评估风险等级 R，原文给出的维度包括&quot;模块跨度、是否核心链路、有无高性能要求、是否涉及资金等高风险场景&quot;。</p></li><li><p>分身的能力等级 L 由&quot;物料的完备度&quot;决定——&quot;物料的完备度将直接决定分身的能力等级&quot;。物料层在四层架构中专门承载规则、项目宪法、应用描述、架构文档、历史经验、编码规范等六类内容。</p></li><li><p>裁决规则走门控：</p><blockquote><p>&quot;R ≤ L才接单，R &gt; L则转交对应负责人。&quot;</p></blockquote><p>能力够就走全流程 Agent 协作交付，不足走人工开发的模式。</p></li><li><p>动态调级：连续成功若干次则可以提升数字分身的能力等级；如果在作业过程中出现多次交付物不符合预期，则需要降低数字分身的能力等级，将门禁收紧。</p></li><li><p>起点限定在简单的小需求（原文给出的范例：&quot;单模块、非核心链路、可自测&quot;），流程跑稳、物料充足后再一点点扩大边界。</p></li></ol><p><strong>前置条件</strong>：风险分级标准成文且维度可枚举；物料清单能反映分身能力等级；需求有统一入口（原文用的是&quot;钉钉机器人&quot;IM 会话，可降级为 issue 或工单系统）。</p><p><strong>适用边界</strong>：风险维度可枚举、有历史交付记录的研发场景。全新业务域无历史参照时 L 无法评估，门禁退化为&quot;全部人工 + 人工判定边界&quot;。</p><p><strong>反例与失败模式</strong>：原文点名两种极端——&quot;因噎废食——顾虑体系建设周期长、见效慢，就迟迟不引入AI&quot;；&quot;急于求成——跳过工程体系与知识库建设，把质量完全押注在模型能力上、依赖反复重试为效果兜底&quot;。另外常见反例是 R 维度写得很细但 L 没有可观测的物料指标，导致门禁变成空判。</p><p><strong>可验证的效果指标</strong>：流水线自动交付的需求占比；L 等级随时间的外扩曲线（从单模块到跨模块、跨应用）；R&gt;L 转人工率及其原因分布；门禁打回后人工复判一致率。</p><p><strong>证据分级</strong>：R/L 裁决与升降级机制可独立复现；R 的具体维度、L 的具体评分需要按自身业务重定；&quot;许多原本难以承接的复杂需求……也能够拆分成若干子需求交给数字分身完成&quot;是阿里云团队的实践描述，不可作为效果承诺。</p><p><strong>一人公司 / 小团队降级</strong>：把门禁做成一张接单 checklist（放进仓库 README 或 Agent 的 Skill 里），四问：跨几个模块？核心链路吗？有高性能或资金相关要求吗？我的物料（规范、Skill、笔记）撑得起吗？四问皆&quot;否&quot;才自动跑；连续做成的同类需求才升一档，翻车一次退回人工重裁。把这条 checklist 当作 IM 机器人或脚本的第一道门。</p><blockquote><p>原文引用：&quot;R ≤ L才接单，R &gt; L则转交对应负责人&quot;；&quot;等流程跑稳了，物料充足了，再一点点扩大边界&quot;。</p></blockquote><h2 id="实践卡-2-契约链——九道工序-交付物说话" tabindex="-1">实践卡 2：契约链——九道工序，交付物说话 <a class="header-anchor" href="#实践卡-2-契约链——九道工序-交付物说话" aria-label="Permalink to &quot;实践卡 2：契约链——九道工序，交付物说话&quot;">​</a></h2><p><strong>要解决的问题</strong>：多 Agent 协作的公认难题是上下文丢失（context loss），原文一句话点透：</p><blockquote><p>&quot;下游需要的信息，上游没有产出&quot;</p></blockquote><p>契约链的解法是把每道工序的输入、输出与合格标准提前固化为契约：上一道工序的输出恰好是下一道工序的输入，工序之间不依赖人工转述与对接。</p><p><strong>具体做法（步骤 / 机制 / 指标）</strong>：</p><ol><li>把交付链路切成九段责任明确的工序：需求门控 → 需求对焦 → 技术方案 → 编码 → 研发自检 → 测试 → 平台质检 → 审计归档 → 人工放行。每一段对应一份正式交付物（spec.md / plan.md / tasks.md / 代码与执行记录 / 自检报告 check_reports / 用例与执行报告 / 质检报告 / 审计归档 / 合并上线确认）。</li><li><strong>硬约束一·强制交付物</strong>：每道工序必须有明确的正式交付物；交付物缺失即视为工序未完成，不允许向下游推进；任何一环要继续流转，必须先拿出一份可被下游直接消费的正式产物。</li><li><strong>硬约束二·交付物驱动的运行时校验</strong>：流水线对每次交接做三重校验——&quot;标签格式、修饰符、发送者身份&quot;，防止 Agent 以口头声明的方式自行推进流水线；被打回的交付物触发上游返工；保证产出不达标就当场打回重做，坏的半成品不往下游工序传递。</li><li><strong>编码分批控制</strong>：编码以 tasks.md 把变更拆分为若干批次，每批次的步频与上下文复杂度控制在模型稳定处理范围内；超出 tasks.md 定义范围的变更会被打回。原文给出的真实案例就是&quot;一处变更超出tasks 定义范围，研发分身重做&quot;。</li><li><strong>契约链是活约束</strong>：契约链不是一次设计完成的静态规范，而是随交付经验持续生长的活约束。原文给出的演化案例：审计曾发现某类需求在技术方案环节反复回改、对话轮次异常偏高；问题的根因是物料层的规则模板缺少对应章节，Agent 进入执行阶段才发现要素不全，只能回改方案再改任务，循环多次；待补齐该规则模板后，同类需求的返工显著减少。</li></ol><p><strong>前置条件</strong>：工序划分与交付物 schema 定义；编排中枢（原文用的是&quot;以状态图描述九阶段流程拓扑&quot;的交付引擎）；可插拔 Skill 作为工序能力载体，可按业务线替换增补。</p><p><strong>适用边界</strong>：多角色、长链路的交付。一次对话能完成的短任务，契约成本大于收益。</p><p><strong>反例与失败模式</strong>：把契约当静态规范一次设计到位（应随交付经验生长）；下游拿不到结构化产物、Agent 用自然语言汇报充数；坏半成品未拦截直接流向下游；交付物校验只看&quot;有没有&quot;，不看&quot;能不能被下游消费&quot;。</p><p><strong>可验证的效果指标</strong>：各工序返工/回改次数；&quot;对话轮次异常偏高&quot;的需求占比（物料缺陷的领先信号）；交付物缺失导致的阻塞次数（应为 0）；超范围变更被拦截次数；单批次编码的上下文 token 用量上限。</p><p><strong>证据分级</strong>：九工序与两条硬约束的机制可复现；check_reports / spec.md / plan.md / tasks.md 的具体 schema 需要按业务重定；&quot;返工显著减少&quot;为阿里云团队内部观察，非公开基准数据。</p><p><strong>一人公司 / 小团队降级</strong>：文件化契约链——需求 → spec.md → plan.md → tasks.md → diff → 自检报告 → 测试报告，每一步只落盘一个正式文件，下一步只消费上一步的文件，不靠聊天记录传话。在 CI 里落两条硬约束：没有 plan.md 不允许开编码 PR；diff 的文件清单超出 tasks.md 范围自动打回。运行时校验的&quot;标签格式、修饰符、发送者身份&quot;可以降级为&quot;commit message 标签 + PR 作者 + 必需文件清单&quot;的脚本校验。</p><blockquote><p>原文引用：&quot;上一道工序的输出恰好是下一道工序的输入&quot;；&quot;交付物缺失即视为工序未完成，不允许向下游推进&quot;；&quot;防止Agent以口头声明的方式自行推进流水线&quot;。</p></blockquote><h2 id="实践卡-3-交叉质检——四个视角独立审查-技术负责人-agent-收口" tabindex="-1">实践卡 3：交叉质检——四个视角独立审查，技术负责人 Agent 收口 <a class="header-anchor" href="#实践卡-3-交叉质检——四个视角独立审查-技术负责人-agent-收口" aria-label="Permalink to &quot;实践卡 3：交叉质检——四个视角独立审查，技术负责人 Agent 收口&quot;">​</a></h2><p><strong>要解决的问题</strong>：代码评审跟不上 Agent 产出（原文：&quot;Agent单次产出代码动辄上万行，最终仍需人逐行审阅，效率难以大幅度提升&quot;）；且模型对自身产出存在系统性偏见——原文点明：</p><blockquote><p>&quot;由于模型层面的偏见，研发分身审查自身产出时，天然倾向于判定交付物符合预期。&quot;</p></blockquote><p>质检环节不能只让 Agent 自查。</p><p><strong>具体做法（步骤 / 机制 / 指标）</strong>：</p><ol><li>自检工序中，产品分身、研发分身、测试分身、安全分身分别开启自己的会话、使用自己的工作区，不共享上下文，只加载 diff、spec、规则与知识库。</li><li>四个视角分工：产品分身核对需求完成度；研发分身检查代码健壮性；安全分身审查修改的合规性；测试分身自动生成用例、执行测试验证，评估功能可靠性。</li><li>四个分身各自输出带证据的结论。</li><li>技术负责人 Agent 收口：四个视角的报告汇总到技术负责人 Agent，对照声明式检查点逐项核验，给出最终判断：&quot;通过或打回&quot;；收口结论若为打回，则触发编码分身返工；直至四个分身均对交付物验收通过，再进入下一环节。</li></ol><p><strong>前置条件</strong>：四个视角的会话隔离环境（独立 workspace，不共享上下文）；声明式检查点清单（可被技术负责人 Agent 机械核验）；视角之间的归责不会因为&quot;看了别人的报告&quot;而引入循环论证。</p><p><strong>适用边界</strong>：质量门禁有清晰评分点的场景；交付物可被 diff 描述的代码改动；不能跨过视角对话泄露上下文，否则四视角独立性失效。</p><p><strong>反例与失败模式</strong>：四视角共享同一个对话历史（独立性丧失）；技术负责人 Agent 不对照检查点而是自由判断（变成第二轮偏见）；质检只产出打分不产出证据（无法做归因）；测试分身只跑 happy path（隐藏的失败模式全部漏网）。</p><p><strong>可验证的效果指标</strong>：每个视角的&quot;带证据结论&quot;覆盖率（应 100%）；技术负责人打回率与人工覆盖周期对比；质检环节的人工介入次数（趋势应单调下降）；质检发现的缺陷按视角分布（用于发现哪个视角有盲区）。</p><p><strong>证据分级</strong>：四视角分工与收口机制可复现；具体的&quot;声明式检查点&quot;内容需要按业务重定；&quot;长期卡住交付的人工瓶颈在这一环被机制正面解开&quot;为团队内部判断，不可作为承诺指标。</p><p><strong>一人公司 / 小团队降级</strong>：用四个独立的 Skill 而非四个会话：一个产品 Skill 跑需求完成度清单、一个开发 Skill 跑健壮性 checklist、一个安全 Skill 跑 SAST/SCA、一个测试 Skill 跑生成的用例；技术负责人 Agent 在汇总前不读对方原始输出，只读&quot;结论+证据+检查点命中情况&quot;三段式结构化报告。CI 里加一条：四个 Skill 任一打回，技术负责人 Agent 不得放行。</p><blockquote><p>原文引用：&quot;不共享上下文，只加载diff、spec、规则与知识库&quot;；&quot;技术负责人Agent&quot;收口；&quot;给出最终判断：通过或打回&quot;。</p></blockquote><h2 id="实践卡-4-数字分身——借人的权限-锚定人的责任" tabindex="-1">实践卡 4：数字分身——借人的权限，锚定人的责任 <a class="header-anchor" href="#实践卡-4-数字分身——借人的权限-锚定人的责任" aria-label="Permalink to &quot;实践卡 4：数字分身——借人的权限，锚定人的责任&quot;">​</a></h2><p><strong>要解决的问题</strong>：Agent 放进生产环境的最大障碍不是技术，而是组织——&quot;把Agent当成一种新的生产要素放进组织&quot;。一旦把 AI 当独立个体，必然撞上三个组织问题：权限怎么管控、出了问题谁负责、谁来迭代优化。</p><p><strong>具体做法（步骤 / 机制 / 指标）</strong>：</p><ol><li>选数字分身而非独立 AI 工程师。原文给出三条理由：&quot;1.权限上，它直接复用被延伸人的权限&quot;；&quot;2.责任上，每一次提交、每一份产出都与该人挂钩&quot;；&quot;3. 被延伸人负责分身的初始化和迭代建设&quot;。</li><li>权限模型：分身借用人的权限作业，行为边界受既有平台权限与审批体系约束；&quot;系统里看到的，始终是人在提交、人在审批&quot;；&quot;分身借人的权限，责任始终锚定在人的身上&quot;。</li><li>装载三步：接消息通道（钉钉机器人或 IM 集成）、建执行环境（云端执行平台或本地 docker）、填领域物料（规则、项目宪法、领域知识）。原文称&quot;前置条件齐备的情况下，单人2-3天完成整个系统的初始化&quot;，可作为时间预算的乐观参照。</li><li>组织角色变化：研发负责人从逐需求执行者转为&quot;物料与Skill治理者 + 关键点裁决者&quot;，人退到需求确认与技术方案确认两个决策点，中间环节交给分身自主作业。</li></ol><p><strong>前置条件</strong>：明确的&quot;被延伸人&quot;（一个负责人绑定一个分身）；既有平台权限与审批体系完备（能直接复用）；物料治理流程（规则、Skill、宪法有 owner）。</p><p><strong>适用边界</strong>：组织已有清晰的代码 owner 与权限体系；个人或小团队里&quot;被延伸人&quot;就是 owner 自己。无法复用既有权限的组织（无 owner、无审批），数字分身退化为&quot;独立 Agent + 全新权限模型&quot;，要先建组织基础设施。</p><p><strong>反例与失败模式</strong>：把分身当作团队公共资源、谁都能调（权限归属模糊）；数字分身绕过既有审批直接动产线；物料 owner 不清，规则互相冲突。</p><p><strong>可验证的效果指标</strong>：分身操作的 commit/PR 100% 落到被延伸人名下；物料 owner 与版本有明确登记；审批链路复用既有 RBAC，不为分身单独开通道。</p><p><strong>证据分级</strong>：权限复用与责任锚定机制可复现；&quot;单人2-3天完成整个系统的初始化&quot;是阿里云团队在&quot;前置条件齐备的情况&quot;下的内部数据，不可直接外推为通用基准；&quot;前置条件齐备&quot;的隐含成本（规则、Skill、宪法已经存在）需要单独评估。</p><p><strong>一人公司 / 小团队降级</strong>：被延伸人就是你自己。分身借用你本机的 Git 凭据、IM 账号与代码仓库权限，所有 commit 与 PR 都落在你名下；物料 owner 也是你，规则冲突立刻显形。装载三步可以合并为一步：把 skill + 规则 + 项目宪法放进同一个仓库，IM 机器人只需指向这个仓库即可。</p><blockquote><p>原文引用：&quot;分身借用人的权限作业，行为边界受既有平台权限与审批体系约束&quot;；&quot;分身借人的权限，责任始终锚定在人的身上&quot;。</p></blockquote><h2 id="实践卡-5-三层审计-loop——交付物越用越强的反哺机制" tabindex="-1">实践卡 5：三层审计 + Loop——交付物越用越强的反哺机制 <a class="header-anchor" href="#实践卡-5-三层审计-loop——交付物越用越强的反哺机制" aria-label="Permalink to &quot;实践卡 5：三层审计 + Loop——交付物越用越强的反哺机制&quot;">​</a></h2><p><strong>要解决的问题</strong>：流水线运行久了会&quot;逐渐腐烂&quot;——规则过期、Skill 失效、知识沉淀断流。原文给出的诊断是：</p><blockquote><p>&quot;为防止整体系统随时间推移的逐渐腐烂，需要把能力渐进式放开与Loop归因反哺融合在作业过程中，推动能力边界向外不断扩展。&quot;</p></blockquote><p><strong>具体做法（步骤 / 机制 / 指标）</strong>：</p><ol><li><strong>触发点</strong>：数字分身每完成一次需求交付，在审计归档工序就自动执行一次审计。</li><li><strong>三层正交扫描</strong>（互不重叠、可独立复核）： <ul><li>数据层：核对需求的规格与方案产物是否齐全；</li><li>产物层：对各过程产物做跨文件联合分析，检测工序间配合度；</li><li>过程层：从会话日志还原执行轨迹，回看 token 消耗、人工介入次数等效率指标。</li></ul></li><li><strong>审计的输出不是打分，而是归因</strong>：归因路由分三条： <ul><li>规则与模板缺陷 → 路由至应用物料迭代；</li><li>技能与工具问题 → 路由至工具链整改；</li><li>知识缺口与错误 → 进入知识库台账，分批建设为结构化知识。</li></ul></li><li><strong>验证与回写</strong>：修正后的物料、知识与规则经验证后全局生效，并在下一次审计与回归评测中复验。</li><li><strong>沉淀原则</strong>：每一次问题都被沉淀为一条能够防止复发的规则；&quot;检测、归因、修正、验证&quot;四步循环往复。</li></ol><p><strong>前置条件</strong>：每道工序的过程记录与会话日志落盘可访问；交付物按工序归类存储；归因路由分类成文；三层扫描工具可独立运行。</p><p><strong>适用边界</strong>：长寿命、多人协作的流水线；交付量足以让审计有意义（低于临界量时审计成本大于收益）。</p><p><strong>反例与失败模式</strong>：审计只打总分不归因（不可操作）；归因路由只挂&quot;个人失误&quot;（掩盖物料缺陷）；修正不经验证就回写；规则模板越加越多但少有废止（噪声爆炸）。</p><p><strong>可验证的效果指标</strong>：归因路由到物料/Skill/知识库的比例分布（用于发现哪一层是主要瓶颈）；每次归因的修正条目数与回归评测通过率；同一类缺陷的复发间隔（应越拉越长）；审计运行耗时占交付总耗时的比例（应稳定下降）。</p><p><strong>证据分级</strong>：三层扫描与归因路由的机制可复现；归因路由的具体分类（规则/Skill/知识）需要按业务重定；&quot;越用越强&quot;&quot;检测、归因、修正、验证四步循环往复使得体系随使用持续变强&quot;是阿里云团队的定性表述，不可作为效果承诺。</p><p><strong>一人公司 / 小团队降级</strong>：三层扫描降级为每周一次的离线脚本：自动扫 commits/PR/会话日志，列出&quot;该写的文件没写&quot;&quot;该跑的命令没跑&quot;&quot;token 异常高的会话&quot;三类清单。归因路由降级为三栏看板：物料问题 / Skill 问题 / 知识缺口；每条问题写明下次复现的预防规则，每月重读一次。</p><blockquote><p>原文引用：&quot;数字分身每完成一次需求交付，在审计归档工序就自动执行一次审计&quot;；&quot;审计的输出不是打分，而是归因&quot;；&quot;每一次问题都被沉淀为一条能够防止复发的规则&quot;。</p></blockquote><h2 id="实践卡-6-成本治理——端到端单需不贵于人工" tabindex="-1">实践卡 6：成本治理——端到端单需不贵于人工 <a class="header-anchor" href="#实践卡-6-成本治理——端到端单需不贵于人工" aria-label="Permalink to &quot;实践卡 6：成本治理——端到端单需不贵于人工&quot;">​</a></h2><p><strong>要解决的问题</strong>：原文把&quot;成本底线&quot;作为未来规划的第一硬约束：&quot;成本底线是端到端做一个需求不能比人工更贵&quot;。模型能力再强，单需成本跑赢人工才能规模化。</p><p><strong>具体做法（步骤 / 机制 / 指标）</strong>：</p><ol><li>三板斧：模型分档、上下文管理、错峰执行。</li><li><strong>模型分档</strong>：根据任务难度（门控 R 的等级、质检复杂度）匹配不同档位的模型；高价模型只跑攻坚环节。</li><li><strong>上下文管理</strong>：把跨工序的&quot;diff、spec、知识库&quot;做按需加载（卡 3 已落），并在卡 5 的过程层扫描里加 token 消耗作为效率指标；上下文越长成本越高，必要时裁剪与摘要。</li><li><strong>错峰执行</strong>：把不紧急的工序（平台质检、审计归档、知识库蒸馏）放在低峰时段跑，把贵模型用得少。</li><li>目标函数：交付成本不随需求量线性上涨。</li></ol><p><strong>前置条件</strong>：单需成本可拆到工序级别；三板斧的开关可以独立触发；有不打扰开发的低峰时段（批处理 / 异步）。</p><p><strong>适用边界</strong>：模型 API 计费是主要成本项的场景；自托管模型时此卡只作为&quot;算力预算分配&quot;参考。</p><p><strong>反例与失败模式</strong>：分档只挂价格不挂质量（便宜的模型关键环节出错成本反而高）；上下文无脑堆&quot;全量历史&quot;；错峰把紧急工序也错峰了，TTM（Time to Market）反而拉长。</p><p><strong>可验证的效果指标</strong>：单需成本中位数与人工成本对比；工序级 token 消耗分布；模型分档使用比例（高价模型应 &lt; 20%）；端到端交付总耗时 vs 人工交付总耗时。</p><p><strong>证据分级</strong>：成本治理的具体手段（模型分档、上下文管理、错峰执行）为原文给出的方向性建议，可复现但需按自价格表重新估算；&quot;不能比人工更贵&quot;是阿里云团队的内部成本底线，不可直接当作行业基准。</p><p><strong>一人公司 / 小团队降级</strong>：模型分档降级为&quot;复杂工序用 Sonnet/Opus 级，简单工序用 MiniMax/Kimi/DeepSeek 级&quot;；上下文管理降级为&quot;每个 Skill 显式声明加载哪些文件，禁止全量塞历史&quot;；错峰降级为&quot;批处理跑知识库蒸馏与物料 lint，IM 即时回应的工序不批处理&quot;。每月算一次&quot;单需花费 ÷ 单需节省时间&quot;，跑不赢人工就降一档。</p><blockquote><p>原文引用：&quot;成本底线是端到端做一个需求不能比人工更贵&quot;；&quot;模型分档、上下文管理、错峰执行&quot;。</p></blockquote><h2 id="七天降级启动顺序-一人公司-小团队" tabindex="-1">七天降级启动顺序（一人公司 / 小团队） <a class="header-anchor" href="#七天降级启动顺序-一人公司-小团队" aria-label="Permalink to &quot;七天降级启动顺序（一人公司 / 小团队）&quot;">​</a></h2><p>把六张卡按一个人也能跑起来的顺序排，第一周打通端到端最小闭环：</p><table tabindex="0"><thead><tr><th>天数</th><th>动作</th><th>对应卡</th></tr></thead><tbody><tr><td>Day 1</td><td>整理一份&quot;物料清单&quot;：仓库 README / 编码规范 / Skill 索引 / 应用描述。物料是 L 的唯一输入，没有物料谈不上门控</td><td>卡 1、卡 4</td></tr><tr><td>Day 2</td><td>写一份接单 checklist（4 问），写进 IM 机器人或 issue 模板。R/L 全人工打分，先跑两周再说自动化</td><td>卡 1</td></tr><tr><td>Day 3</td><td>把最小契约链落盘：spec.md → plan.md → tasks.md → diff → 自检报告 → 测试报告。每一步只允许落一个文件，不靠聊天记录传话</td><td>卡 2</td></tr><tr><td>Day 4</td><td>在 CI 里落两条硬约束：没有 plan.md 不允许开 PR；diff 文件清单超出 tasks.md 自动打回</td><td>卡 2</td></tr><tr><td>Day 5</td><td>用四个独立 Skill 跑四视角交叉质检，技术负责人 Agent 只读结构化结论不读原始对话</td><td>卡 3</td></tr><tr><td>Day 6</td><td>写一份每周离线审计脚本：三栏看板（物料/Skill/知识），每条归因对应一条预防规则</td><td>卡 5</td></tr><tr><td>Day 7</td><td>算一次&quot;单需成本 ÷ 单需节省时间&quot;，跑不赢人工就降档；模型分档与上下文裁剪同步落</td><td>卡 6</td></tr></tbody></table><p>这一周跑下来就有了契约链 + 门控 + 质检 + 审计 + 成本治理的最小骨架；后面四周再扩到跨模块、跨应用的需求。</p><h2 id="与现有页面的重叠和插入位置" tabindex="-1">与现有页面的重叠和插入位置 <a class="header-anchor" href="#与现有页面的重叠和插入位置" aria-label="Permalink to &quot;与现有页面的重叠和插入位置&quot;">​</a></h2><p>建议落点：新增一页 <code>docs/zh/practice/agent-delivery-pipeline.md</code>（本页草稿即适配该路径），与现有页面的关系：</p><table tabindex="0"><thead><tr><th>现有页面</th><th>重叠点</th><th>处理建议</th></tr></thead><tbody><tr><td><code>docs/zh/practice/index.md</code>（企业实践目录）</td><td>无内容重叠，但只列了&quot;形势 → 采购&quot;两节，缺交付流水线</td><td>在目录的&quot;按决策顺序读&quot;小节加第三节：&quot;3. 怎么交付：<a href="/zh/practice/agent-delivery-pipeline.html">端到端交付流水线</a>&quot;</td></tr><tr><td><code>docs/zh/practice/procurement-plan.md</code></td><td>都关心&quot;AI 在研发里怎么落地&quot;，但本章聚焦&quot;流水线&quot;而非&quot;采购&quot;</td><td>与采购页互链，互补关系——采购页说&quot;买什么 API 与 IDE&quot;，本章说&quot;买来之后怎么接&quot;</td></tr><tr><td><code>docs/zh/practice/reporter.md</code>（Vibe Coding 报告）</td><td>都引用了&quot;代码量上升但交付效率未同步跃升&quot;的现象描述</td><td>不重复现象，在 reporter 末尾加相关阅读链向本页；本章只讲机制，不复述行业数据</td></tr><tr><td><code>docs/practice/ai-efficiency-practice.md</code></td><td>两条主张与本章部分吻合：&quot;AI 辅助需求到测试全流程&quot;&quot;Prompt 即需求文档&quot;。但 ai-efficiency 是单团队（齐淼树技术团队）的总结，本章是阿里云云通信团队的方法论</td><td>互链，标出区别：ai-efficiency 强调&quot;AI 提效&quot;，本章强调&quot;端到端交付&quot;。两者的&quot;40%+&quot;是 ai-efficiency 团队反馈，与本章的内部数据无关</td></tr><tr><td><code>docs/practice/ai-landing-discussion.md</code></td><td>三处共识：场景选择优先于技术选型、数据是瓶颈、草稿 + 人工审核。本章里&quot;先简单需求起步&quot;&quot;物料的完备度决定能力&quot;&quot;契约链强制交付物&quot;是这些共识在工程化上的更具体落法</td><td>在 ai-landing 页脚加相关阅读链向本页；本章在卡 1/卡 2 复述共识时给出工程化版本</td></tr><tr><td><code>docs/practice/ai-native-hiring.md</code></td><td>主张&quot;人类角色从执行者转为审核者&quot;，与本章&quot;研发负责人从逐需求执行者转为物料与Skill治理者 + 关键点裁决者&quot;高度一致</td><td>在 ai-native-hiring 页相关阅读中加链；本章卡 4 直接引用其原文表述以保留人设同源</td></tr></tbody></table><p>整合后的实践栏目结构（建议）：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>docs/zh/practice/</span></span>
<span class="line"><span>├── index.md                       # 目录（增加第三节&quot;怎么交付&quot;）</span></span>
<span class="line"><span>├── reporter.md                    # 行业形势（已有）</span></span>
<span class="line"><span>├── procurement-plan.md            # 采购与实施（已有）</span></span>
<span class="line"><span>└── agent-delivery-pipeline.md     # 本页（新增）</span></span></code></pre></div><p>英文站 <code>docs/practice/</code> 不在本章交付范围内，但四篇英文页面（<code>ai-efficiency-practice.md</code>、<code>ai-landing-discussion.md</code>、<code>ai-native-hiring.md</code>、<code>index.md</code>）已经在互链分析中考虑。</p><h2 id="写在最后-本章最值得搬走的-不是数字" tabindex="-1">写在最后：本章最值得搬走的，不是数字 <a class="header-anchor" href="#写在最后-本章最值得搬走的-不是数字" aria-label="Permalink to &quot;写在最后：本章最值得搬走的，不是数字&quot;">​</a></h2><p>原文给出了&quot;返工显著减少&quot;&quot;越用越强&quot;等定性描述，但都来自单一团队的内部观察，未公开基准，<strong>不可作为效果承诺</strong>。可搬走的是六张卡的机制——门控、契约、质检、权限、审计、成本。本章落款用一句话收束：</p><blockquote><p>&quot;真正靠得住的不是模型能力，而是围绕模型建起的一整套交付体系与资产。&quot;</p></blockquote><p>把这一套搬到自己的仓库里，把数字留给自己的仪表盘。</p>`,96)])])}const m=o(u,[["render",a]]);export{k as __pageData,m as default};
